
'use strict';
(()=>{const app=document.querySelector('#support-app'),alert=document.querySelector('#support-alert');const labels={open:'مفتوحة',waiting:'بانتظار ردك',closed:'مغلقة'},categories={technical:'مشكلة تقنية',billing:'اشتراك أو استرداد',design:'تصميم بطاقة',privacy:'طلب خصوصية',complaint:'شكوى',other:'طلب آخر'},roles={guest:'زائر · بيانات تواصل غير متحقق منها',owner:'صاحب نشاط',employee:'موظف',customer:'عميل ولاء',admin:'إدارة'};let kind='guest',tickets=[],selected=null,creating=false,busy=false,offset=0,total=0,filter='',search='',request=0;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=v=>new Date(v).toLocaleString('ar-SA',{dateStyle:'medium',timeStyle:'short'});
 const options=(data,value)=>Object.entries(data).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');
 async function api(path,body){const r=await fetch('/api/support/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'تعذر تنفيذ الطلب.');return data;}
 function error(e){alert.className='support-error';alert.textContent=e.name==='TimeoutError'?'تأخر الاتصال. اضغط تحديث للتحقق من النتيجة قبل إعادة الإرسال.':e.message;}
 function clear(){alert.textContent='';alert.className='';}
 function form(){return `<h2>تذكرة جديدة</h2><p class="support-hint">اذكر ما حدث وما الذي تحتاج مساعدتنا فيه. ${kind==='guest'?'تُحفظ متابعة تذاكرك في هذا المتصفح لمدة تصل إلى ٣٠ يومًا. حذف بيانات المتصفح أو استخدام جهاز آخر قد يفقد الوصول؛ سجّل الدخول أولًا إذا أردت ربطها بحسابك. لا يثبت إدخال البريد ملكيته.':'التذكرة مرتبطة بحسابك الحالي ويمكن متابعتها بعد تسجيل الدخول.'}</p>${kind==='guest'?'<a href="/login" class="info-button">تسجيل الدخول وربط التذكرة بحسابك</a>':''}<form id="support-create">${kind==='guest'?'<label class="support-field">اسمك<input name="name" maxlength="60" autocomplete="name" required></label><label class="support-field">البريد للتواصل<input name="email" type="email" maxlength="254" autocomplete="email" dir="ltr" required></label>':''}<label class="support-field">نوع الطلب<select name="category">${options(categories,'technical')}</select></label><label class="support-field">عنوان الطلب<input name="subject" minlength="4" maxlength="120" required></label><label class="support-field">التفاصيل<textarea name="message" minlength="10" maxlength="4000" required placeholder="اشرح المشكلة والخطوات التي أدت إليها، بدون بيانات حساسة."></textarea></label><button class="info-button gold" type="submit">إرسال التذكرة ↗</button></form>`;}
 function detail(){if(creating)return form();if(!selected)return '<h2>كل طلب، له متابعة.</h2><p class="support-hint">اختر تذكرة للاطلاع على المحادثة، أو افتح تذكرة جديدة.</p>';const t=selected;return `<div class="support-row"><span class="support-status ${esc(t.status)}">${kind==='admin'&&t.status==='waiting'?'بانتظار العميل':labels[t.status]}</span><small dir="ltr">${esc(t.reference)}</small></div><h2>${esc(t.subject)}</h2><div class="support-meta"><span>${categories[t.category]}</span><span>${date(t.created)}</span>${kind==='admin'?`<span>${esc(t.name)} · ${roles[t.kind]}</span>${t.email?`<span dir="ltr">${esc(t.email)}</span>`:''}`:''}</div>${kind==='admin'?`<label class="support-field">حالة التذكرة<select id="support-status">${options({...labels,waiting:'بانتظار العميل'},t.status)}</select></label>`:''}<div class="support-messages">${t.messages.map(m=>`<section class="support-message ${m.author==='support'?'from-support':''}"><div class="support-row"><strong>${m.author==='support'?'دعم رِجعة':kind==='admin'?esc(t.name):'أنت'}</strong><small>${date(m.time)}</small></div><p>${esc(m.body)}</p></section>`).join('')}</div><form id="support-reply"><label class="support-field">${kind==='admin'?'الرد على العميل':'أضف ردًا أو توضيحًا'}<textarea name="message" maxlength="4000" required></textarea></label>${t.status==='closed'?'<p class="support-hint">إرسال رد جديد يعيد فتح متابعة التذكرة.</p>':''}<button type="submit" class="info-button gold">إرسال الرد ↗</button></form>`;}
 function render(){document.querySelector('#support-title').textContent=kind==='admin'?'إدارة الدعم والتذاكر':'الدعم والتذاكر';app.innerHTML=`<div class="support-toolbar"><div><button class="info-button gold" data-support="new">تذكرة جديدة ＋</button><button class="info-button" data-support="refresh">تحديث ↻</button></div><div>${kind==='admin'?`<input id="support-search" aria-label="البحث في التذاكر" placeholder="رقم التذكرة أو العنوان أو الاسم" value="${esc(search)}"><select id="support-filter" aria-label="تصفية الحالة"><option value="">جميع الحالات</option>${options({...labels,waiting:'بانتظار العميل'},filter)}</select><button class="info-button" data-support="search">بحث</button>`:''}</div></div><div class="support-columns"><aside><div class="support-list">${tickets.length?tickets.map(t=>`<button class="support-ticket ${selected?.id===t.id?'selected':''}" data-support="open" data-id="${esc(t.id)}"><div class="support-row"><small dir="ltr">${esc(t.reference)}</small><span class="support-status ${esc(t.status)}">${kind==='admin'&&t.status==='waiting'?'بانتظار العميل':labels[t.status]}</span></div><strong>${esc(t.subject)}</strong><small>${kind==='admin'?esc(t.name)+' · ':''}${date(t.updated)}</small></button>`).join(''):'<p class="support-empty">لا توجد تذاكر في هذه القائمة.</p>'}</div><div class="support-pagination"><button class="info-button" data-support="prev" ${offset===0?'disabled':''}>السابق</button><span>${total?' '+Math.floor(offset/50+1)+' / '+Math.ceil(total/50):'٠'}</span><button class="info-button" data-support="next" ${offset+50>=total?'disabled':''}>التالي</button></div></aside><article class="support-detail">${detail()}</article></div>`;}
 async function list(){const seq=++request;const data=await api('tickets?offset='+offset+'&status='+encodeURIComponent(filter)+'&q='+encodeURIComponent(search));if(seq!==request)return;kind=data.kind;tickets=data.tickets;total=data.total;const back=document.querySelector('.info-header .info-button');if(kind==='admin'&&back){back.href='/admin';back.textContent='العودة للإدارة ↗';}render();}
 app.addEventListener('click',async e=>{const b=e.target.closest('[data-support]');if(!b||busy)return;clear();try{if(b.dataset.support==='new'){creating=true;selected=null;render();}else if(b.dataset.support==='open'){busy=true;b.disabled=true;const data=await api('ticket?id='+encodeURIComponent(b.dataset.id));selected=data.ticket;creating=false;await api('seen',{id:selected.id,seen:Math.max(...selected.messages.map(m=>m.time))});render();}else{if((creating||document.querySelector('#support-reply textarea')?.value)&&!confirm('يوجد نص لم يُرسل. هل تريد تحديث القائمة؟'))return;creating=false;if(b.dataset.support==='search'){search=document.querySelector('#support-search').value;filter=document.querySelector('#support-filter').value;offset=0;}if(b.dataset.support==='prev')offset=Math.max(0,offset-50);if(b.dataset.support==='next')offset+=50;if(selected)selected=(await api('ticket?id='+encodeURIComponent(selected.id))).ticket;await list();}}catch(e){error(e);}finally{busy=false;b.disabled=false;}});
 app.addEventListener('change',async e=>{if(e.target.id!=='support-status'||busy||!selected)return;busy=true;e.target.disabled=true;clear();try{selected=(await api('status',{id:selected.id,status:e.target.value})).ticket;await list();}catch(err){error(err);render();}finally{busy=false;}});
 app.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,d=new FormData(f),button=f.querySelector('button');busy=true;button.disabled=true;button.textContent='جارٍ الإرسال…';clear();try{const body=Object.fromEntries(d);if(f.id==='support-reply')body.id=selected.id;const data=await api(f.id==='support-create'?'create':'reply',body);selected=data.ticket;creating=false;offset=0;await list();alert.textContent='تم حفظ الطلب. تابع الردود هنا داخل التذكرة.';}catch(e){error(e);button.disabled=false;button.textContent='إرسال ↗';}finally{busy=false;}});
 let noticeBusy=false;async function notifications(){if(document.hidden||noticeBusy)return;noticeBusy=true;try{const data=await api('summary');let box=document.querySelector('#support-notifications');if(!box){box=document.createElement('p');box.id='support-notifications';box.setAttribute('role','status');document.querySelector('#support-intro').after(box);}box.textContent=data.unread?`${data.unread} تذاكر فيها رسائل جديدة — اضغط تحديث لعرضها.`:'';}catch{}finally{noticeBusy=false;}}setInterval(notifications,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)notifications();});notifications();
 list().catch(e=>{error(e);app.innerHTML='<button class="info-button" onclick="location.reload()">إعادة المحاولة</button>';});
})();
